<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Animated Solar System</title>
<style>
  body,html{margin:0;padding:0;background:#000;overflow:hidden}
  canvas{display:block}
</style>
</head>
<body>
<canvas id="space"></canvas>
<script>
(() => {
  const canvas = document.getElementById('space');
  const ctx = canvas.getContext('2d');
  const resize = () => {
    canvas.width = innerWidth;
    canvas.height = innerHeight;
  };
  window.addEventListener('resize', resize);
  resize();

  // ---- starfield background ----
  const STAR_COUNT = 300;
  const stars = [];
  for (let i = 0; i < STAR_COUNT; i++) {
    stars.push({
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height,
      r: Math.random() * 1.2 + 0.2,
      alpha: Math.random() * 0.5 + 0.5
    });
  }

  // ---- planet data ---- (distance & size are scaled for visibility)
  const planets = [
    {name:'Mercury',  color:'#b1b1b1', dist:70,  r:4,  period:88},
    {name:'Venus',    color:'#e5c07b', dist:100, r:6,  period:225},
    {name:'Earth',    color:'#61afef', dist:140, r:6,  period:365},
    {name:'Mars',     color:'#ff6c6b', dist:180, r:5,  period:687},
    {name:'Jupiter',  color:'#ffb86c', dist:260, r:12, period:4333},
    {name:'Saturn',   color:'#d19a66', dist:340, r:10, period:10759},
    {name:'Uranus',   color:'#56b6c2', dist:400, r:9,  period:30687},
    {name:'Neptune',  color:'#c678dd', dist:460, r:9,  period:60190}
  ];
  const SUN = {color:'#ffdd55', r:20};

  const speedFactor = 0.05; // makes orbits fast enough to see

  function drawStars() {
    ctx.save();
    ctx.fillStyle = '#fff';
    stars.forEach(s => {
      ctx.globalAlpha = s.alpha;
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI*2);
      ctx.fill();
    });
    ctx.restore();
  }

  function drawOrbit(dist) {
    ctx.save();
    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(canvas.width/2, canvas.height/2, dist, 0, Math.PI*2);
    ctx.stroke();
    ctx.restore();
  }

  function draw() {
    ctx.clearRect(0,0,canvas.width,canvas.height);
    drawStars();

    const cx = canvas.width/2;
    const cy = canvas.height/2;
    const now = performance.now()/1000; // seconds

    // Sun
    ctx.save();
    ctx.fillStyle = SUN.color;
    ctx.beginPath();
    ctx.arc(cx, cy, SUN.r, 0, Math.PI*2);
    ctx.fill();
    ctx.font = "14px sans-serif";
    ctx.fillStyle = "#fff";
    ctx.textAlign = "center";
    ctx.fillText('Sun', cx, cy - SUN.r - 6);
    ctx.restore();

    // Planets
    planets.forEach(p => {
      drawOrbit(p.dist);
      const angle = now * (2*Math.PI / p.period) * speedFactor;
      const x = cx + Math.cos(angle) * p.dist;
      const y = cy + Math.sin(angle) * p.dist;

      ctx.save();
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(x, y, p.r, 0, Math.PI*2);
      ctx.fill();

      // label
      ctx.font = "12px sans-serif";
      ctx.fillStyle = "#fff";
      ctx.textAlign = "center";
      ctx.fillText(p.name, x, y - p.r - 4);
      ctx.restore();
    });

    requestAnimationFrame(draw);
  }

  draw();
})();
</script>
</body>
</html>
```

The script creates a full‑screen canvas, draws a static starfield, then each animation frame computes each planet’s angle from its orbital period and draws the Sun, orbital rings, moving planets, and their labels.
